package fr.marstech.e2e

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test
import java.util.UUID

internal class ChecklistE2eTest : E2eTest() {

    // Lazy: the server port is injected after construction
    private val auth by lazy { mapOf(apiKey("checklist-${UUID.randomUUID()}")) }

    // Item ids are generated by the server; a client itemId must name an existing item
    private val template = """{"title":"Release","items":[{"label":"Build"},{"label":"Tag"},{"label":"Notes"}]}"""

    private fun itemIds(templateId: String): List<String> =
        get("/api/checklists/templates/$templateId", auth).json()["items"].let { items ->
            (0 until items.size()).map { items[it]["itemId"].asString() }
        }

    private fun createTemplate(): String {
        val created = postJson("/api/checklists/templates", template, auth)
        assertEquals(201, created.statusCode(), created.body())
        return created.json()["id"].asString()
    }

    private fun createInstance(templateId: String, context: String = "v1.0.0"): String {
        val created = postJson("/api/checklists/instances", """{"templateId":"$templateId","context":"$context"}""", auth)
        assertEquals(201, created.statusCode(), created.body())
        return created.json()["id"].asString()
    }

    @Test
    fun shouldRunTemplateLifecycleWithOptimisticLocking() {
        val id = createTemplate()
        val read = get("/api/checklists/templates/$id", auth).json()
        val version = read["version"].asLong()
        assertEquals(3, read["items"].size())

        val build = read["items"][0]["itemId"].asString()
        val replace = """{"title":"Release v2","items":[{"itemId":"$build","label":"Build"}],"version":$version}"""
        val replaced = sendJson("PUT", "/api/checklists/templates/$id", replace, auth)
        assertEquals(200, replaced.statusCode(), replaced.body())

        // Same version again: stale, refused
        assertEquals(409, sendJson("PUT", "/api/checklists/templates/$id", replace, auth).statusCode())

        assertEquals(204, delete("/api/checklists/templates/$id", auth).statusCode())
        assertEquals(404, get("/api/checklists/templates/$id", auth).statusCode())
    }

    @Test
    fun shouldTrackInstanceProgressAndKeepItsSnapshot() {
        val templateId = createTemplate()
        val (build, _, notes) = itemIds(templateId)
        val id = createInstance(templateId)

        fun patch(item: String, status: String) =
            sendJson("PATCH", "/api/checklists/instances/$id/items/$item", """{"status":"$status"}""", auth)

        assertEquals(200, patch(build, "DONE").statusCode())
        val afterSkip = patch(notes, "SKIPPED")
        assertEquals(200, afterSkip.statusCode())
        // DONE / (total - SKIPPED) = 1 / 2
        assertEquals(50, afterSkip.json()["progressPercent"].asInt())

        // Editing the template never alters a running instance
        val version = get("/api/checklists/templates/$templateId", auth).json()["version"].asLong()
        val replaced = sendJson("PUT", "/api/checklists/templates/$templateId", """{"title":"Other","items":[{"label":"x"}],"version":$version}""", auth)
        assertEquals(200, replaced.statusCode(), replaced.body())
        assertEquals(1, get("/api/checklists/templates/$templateId", auth).json()["items"].size())
        assertEquals(3, get("/api/checklists/instances/$id", auth).json()["items"].size())

        val listed = get("/api/checklists/instances?templateId=$templateId&context=v1.0.0", auth)
        assertEquals(200, listed.statusCode())

        assertEquals(400, patch(build, "MAYBE").statusCode())
        assertEquals(404, patch("unknown-item", "DONE").statusCode())
        assertEquals(204, delete("/api/checklists/instances/$id", auth).statusCode())
        assertEquals(404, get("/api/checklists/instances/$id", auth).statusCode())
    }

    @Test
    fun shouldIsolateNamespaces() {
        val id = createTemplate()
        val other = mapOf(apiKey("checklist-other-${UUID.randomUUID()}"))
        assertEquals(404, get("/api/checklists/templates/$id", other).statusCode())
        assertEquals(200, get("/api/checklists/templates/$id", auth).statusCode())
    }

    @Test
    fun shouldRequireValidKeyAndInput() {
        assertEquals(401, get("/api/checklists/templates").statusCode())
        assertEquals(401, get("/api/checklists/templates", mapOf("X-Api-Key" to "malformed")).statusCode())
        assertEquals(400, postJson("/api/checklists/templates", """{"title":"","items":[]}""", auth).statusCode())
        assertEquals(400, postJson("/api/checklists/templates", """{"title":"t","items":[{"itemId":"nope","label":"x"}]}""", auth).statusCode())
        assertEquals(404, postJson("/api/checklists/instances", """{"templateId":"unknown"}""", auth).statusCode())
        assertEquals(400, get("/api/checklists/templates?size=0", auth).statusCode())
    }
}
